"""Gradle init script that resolves from the system jar repository."""

from __future__ import annotations

from pathlib import Path

from sysjar.model import Index, groovy_quote


def render_init_script(index: Index, repo: Path, *, strict_repos: bool = False, keep_repos: bool = False) -> str:
    mapping = index.version_map()
    lines = [
        "// Generated by sysjar. One system jar per library, the way a shared library works.",
        "def sysjarVersion = [",
    ]
    for key, version in sorted(mapping.items()):
        lines.append(f"  {groovy_quote(key)}: {groovy_quote(version)},")
    lines.append("]")
    lines.append(f"def sysjarRepoUrl = {groovy_quote(repo.resolve().as_uri())}")
    mode = "FAIL_ON_PROJECT_REPOS" if strict_repos else "PREFER_SETTINGS"
    lines.append(f"def sysjarClearProjectRepos = {str(not keep_repos).lower()}")
    lines.append(f"def sysjarRepoMode = '{mode}'")
    lines.append(_BODY)
    return "\n".join(lines) + "\n"


_BODY = r"""
def sysjarForce = { resolutionStrategy ->
  resolutionStrategy.dependencySubstitution {
    all { dependency ->
      def requested = dependency.requested
      if (!(requested instanceof org.gradle.api.artifacts.component.ModuleComponentSelector)) {
        return
      }
      def key = "${requested.group}:${requested.module}".toString()
      def version = sysjarVersion[key]
      if (version != null && requested.version != version) {
        dependency.useTarget("${key}:${version}".toString(), "OpenMandriva system jar")
      }
    }
  }
  resolutionStrategy.eachDependency { details ->
    def key = "${details.requested.group}:${details.requested.name}".toString()
    def version = sysjarVersion[key]
    if (version != null) {
      details.useVersion(version)
      details.because("OpenMandriva system jar")
    }
  }
}

def sysjarAddRepo = { handler ->
  handler.maven {
    name = "sysjar"
    url = sysjarRepoUrl
  }
}

settingsEvaluated { settings ->
  settings.pluginManagement.repositories.clear()
  sysjarAddRepo(settings.pluginManagement.repositories)
  settings.dependencyResolutionManagement.repositoriesMode.set(
    org.gradle.api.initialization.resolve.RepositoriesMode.valueOf(sysjarRepoMode))
  settings.dependencyResolutionManagement.repositories.clear()
  sysjarAddRepo(settings.dependencyResolutionManagement.repositories)
}

allprojects { project ->
  sysjarAddRepo(project.buildscript.repositories)
  project.buildscript.configurations.configureEach { cfg ->
    sysjarForce(cfg.resolutionStrategy)
  }
  project.configurations.configureEach { cfg ->
    sysjarForce(cfg.resolutionStrategy)
  }
  project.plugins.withId("java") {
    project.tasks.named("jar").configure { task ->
      task.doLast {
        def dir = new File(project.rootProject.projectDir, ".sysjar/reactor")
        dir.mkdirs()
        def label = project.path == ":" ? "_root" : project.path.replace(":", "_")
        def deps = []
        try {
          def cfg = project.configurations.findByName("runtimeClasspath")
          if (cfg != null) {
            cfg.incoming.resolutionResult.allDependencies { dep ->
              if (dep instanceof org.gradle.api.artifacts.result.ResolvedDependencyResult) {
                def id = dep.selected.id
                if (id instanceof org.gradle.api.artifacts.component.ModuleComponentIdentifier) {
                  deps << [group: id.group, artifact: id.module, version: id.version, scope: "runtime"]
                }
              }
            }
          }
        } catch (Exception ignored) {
        }
        def pom = new File(project.projectDir, "pom.xml")
        def payload = [
          group: project.group?.toString() ?: "",
          artifact: project.name?.toString() ?: "",
          version: project.version?.toString() ?: "",
          jar: task.archiveFile.get().asFile.absolutePath,
          pom: pom.isFile() ? pom.absolutePath : "",
          dependencies: deps,
        ]
        new File(dir, label + ".json").text = groovy.json.JsonOutput.toJson(payload)
      }
    }
  }
}

if (sysjarClearProjectRepos) {
  gradle.projectsEvaluated {
    gradle.rootProject.allprojects { project ->
      project.repositories.clear()
      sysjarAddRepo(project.repositories)
    }
  }
}
"""


def write_init_script(path: Path, index: Index, repo: Path, **kwargs) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(render_init_script(index, repo, **kwargs), encoding="utf-8")
    return path
